+
+const execAsync = promisify(exec);
+
+export function createSandbox() {
+    return async (node: any, inputData: any[]) => {
+        const userCode = node.parameters.functionCode;
+
+        // Create a temporary file with the user's code
+        const tempDir = tmpdir();
+        const tempFile = join(tempDir, `python_node_${Date.now()}.py`);
+
+        try {
+            // Write the user code with restricted imports
+            const restrictedCode = `
+__builtins__.__dict__.clear()
+__builtins__.__dict__.update({
+    'range': range,
+    'len': len,
+    'str': str,
+    'int': int,
+    'float': float,
+    'bool': bool,
+    'list': list,
+    'dict': dict,
+    'tuple': tuple,
+    'set': set,
+    'min': min,
+    'max': max,
+    'sum': sum,
+    'sorted': sorted,
+    'enumerate': enumerate,
+    'zip': zip,
+    'filter': filter,
+    'map': map,
+})
+
+import sys
+sys.path = []  # Clear module search path
+
+${userCode}
+`;
+
+            await writeFile(tempFile, restrictedCode);
+
+            // Execute with limited permissions
+            const { stdout, stderr } = await execAsync(
+                `python3 -B -E -c "import sys; sys.dont_write_bytecode = True; exec(open('${tempFile}').read())"`,
+                { timeout: 10000 }
+            );
+
+            return stdout;
+        } finally {
+            // Clean up
+            try { await unlink(tempFile); } catch (e) {}
+        }
+    };
+}

